def main():
    data=load(APP_ASSET); patch=load(PATCH_ASSET)
    if data!=patch: raise SystemExit('app/patch diagnostics differ before batch10')
    if len(data.get('scenarios',[]))!=136: raise SystemExit('unexpected scenario count')
    by={s['id']:s for s in data['scenarios']}
    if not TARGETS<=by.keys(): raise SystemExit('missing batch10 scenarios')
    for sid in sorted(TARGETS):
        s=by[sid]
        apply_route(s,**ROUTES[sid])
        s.setdefault('actions',[{}])
        if not s['actions']: s['actions']=[{}]
        s['actions'][0]={'summary':'Зафиксировать наблюдаемые признаки и локализовать отказ по безопасному диагностическому дереву; ремонтные/обходные действия только по действующему профильному источнику.','sourceBound':False,'riskClass':'normal','userFacingPolicy':'TRIAGE_ONLY_NO_REPAIR'}
        s['sourceAudit']={'auditedAt':V,'scope':'p0_auxiliaries_batch10','status':'IMPROVE','method':'manufacturer + current procedure + independent legacy cross-check'}
        s['sourceAgeNote']='Batch10 27.09.2026: заводские РЭ используются как техническая база раннего исполнения; №996/р — только актуальный процедурный cross-check там, где он применим; старая памятка — HISTORICAL. Обозначения, температурные алгоритмы и уставки не переносить на поздние исполнения без подтверждения профиля.'
        for r in (R1,R2,R5,R7,R996,LEGACY): addref(s,r)
        if sid in {'ER-DIAG-071','ER-DIAG-073'}: addref(s,R6)
        if sid=='ER-DIAG-073': addref(s,BRAKES)
    dump(APP_ASSET,data); dump(PATCH_ASSET,data)
    if APP_ASSET.read_bytes()!=PATCH_ASSET.read_bytes(): raise SystemExit('app/patch differ after batch10')
    print('ERMAK_P0_AUXILIARIES_BATCH10='+','.join(sorted(TARGETS)))

if __name__=='__main__':
    main()
